from pathlib import Path
import tempfile,subprocess
root=Path(__file__).resolve().parents[2]
def extract(name,sig):
 s=next((root/'src').rglob(name+'.java')).read_text();a=s.index(sig);b=s.index('{',a);i=b+1;depth=1
 while depth:
  depth+=(s[i]=='{')-(s[i]=='}');i+=1
 return s[a:i]
methods='\n'.join(extract('NpcQuestTransactions',x) for x in ['static void tutorialArmor(', 'static void iceCaveSupplies(', 'private static void grantMissingRange('])
teleport=extract('L1NpcTeleportAction','public L1NpcHtml execute(')
java='''import java.util.*;
public class Check {
 static int cases,checks;static void ck(boolean b){checks++;if(!b)throw new AssertionError("case="+cases+" check="+checks);}
 static class L1Object{} static class L1NpcInstance extends L1Object{int getId(){return 9;}int getNpcId(){return 9274;}L1NpcInstance getNpcTemplate(){return this;}String get_name(){return "NPC";}}
 static class L1ItemInstance{int id,count;L1ItemInstance(int i,int n){id=i;count=n;}int getCount(){return count;}String getLogName(){return id+":"+count;}}
 static class Inv{Map<Integer,Integer> owned=new HashMap<>();int debitResult=-1,removes;boolean checkItem(int id,int n){return owned.getOrDefault(id,0)>=n;}L1ItemInstance findItemId(int i){return owned.containsKey(i)?new L1ItemInstance(i,owned.get(i)):null;}int removeItem(L1ItemInstance i,int n){removes++;int take=debitResult<0?n:debitResult;owned.merge(i.id,-take,Integer::sum);return take;}}
 static class L1PcInstance{Inv inv=new Inv();int cls,level=50,fail,submits,teleports,tx,randomX;List<String> pages=new ArrayList<>(),msgs=new ArrayList<>();Runnable done,rollback;Inv getInventory(){return inv;}boolean isKnight(){return cls==0;}boolean isCrown(){return cls==1;}boolean isDarkelf(){return cls==2;}boolean isDragonknight(){return cls==3;}int getLevel(){return level;}void start_teleport(int x,int y,int m,int h,int z,boolean e,boolean b){teleports++;randomX=x;}}
 static class L1InventoryTransaction implements AutoCloseable{L1PcInstance p;int step;Map<Integer,Integer> staged=new HashMap<>();Runnable fail;boolean submitted;static L1InventoryTransaction begin(L1PcInstance p,int key){if(p.fail==1||p.tx!=0)throw new IllegalStateException();p.tx=1;L1InventoryTransaction t=new L1InventoryTransaction();t.p=p;t.step=1;return t;}L1ItemInstance grant(int i,int n){if(++step==p.fail)return null;staged.put(i,n);return new L1ItemInstance(i,n);}void onFailure(Runnable r){fail=r;}void commitAfterInventoryRelease(Runnable r){if(p.fail==8)throw new IllegalStateException();submitted=true;p.submits++;p.done=()->{p.inv.owned.putAll(staged);p.tx=0;p.done=null;r.run();};p.rollback=()->{p.tx=0;p.done=null;fail.run();};}public void close(){if(!submitted)p.tx=0;}}
 static class SC_NPCTalkReturn{static void send(L1PcInstance p,int id,String page){ck(id==9);p.pages.add(page);}}
 static class SC_ServerMessage{static void send(L1PcInstance p,int code,String... args){p.msgs.add(code+":"+String.join(":",args));}}
 static class SC_SystemMessage{static void send(L1PcInstance p,String msg){p.msgs.add(msg);}}
 static class L1NpcHtml{static final L1NpcHtml HTML_CLOSE=new L1NpcHtml();}
 static class L1ItemId{static final int ADENA=40308;}
 static class L1Location{int x,y,map;boolean valid;static boolean badRandom;L1Location(int m,boolean v){map=m;valid=v;x=10;y=20;}int getX(){return x;}int getY(){return y;}int getMapId(){return map;}L1Location getMap(){return this;}boolean isInMap(int x,int y){return valid;}static L1Location randomLocation(L1Location l,int a,int b,boolean c){L1Location r=new L1Location(l.map,!badRandom);r.x=11;return r;}}
 static class Teleport{L1Location _loc;int _price,_heading;boolean _effect=true;
'''+teleport+''' }
'''+methods+'''
 static void grantCase(int cls,int kind,int mask,int fail,int mode){cases++;L1PcInstance p=new L1PcInstance();p.cls=cls;p.fail=fail;int first=kind==0?(cls<4?22300:22306):kind==1?30055:30056;int size=kind==0?5:1,quantity=kind==0?1:kind==1?120:100;String ok=kind==0?"tutorrw5":kind==1?"icqwand2":"icqwand3",already=kind==0?"tutorrw6":"icqwand4";for(int i=0;i<size;i++)if((mask&(1<<i))!=0)p.inv.owned.put(first+i,1);Map<Integer,Integer> before=new HashMap<>(p.inv.owned);int missing=size-before.size();if(kind==0)tutorialArmor(p,new L1NpcInstance());else iceCaveSupplies(p,new L1NpcInstance(),kind==1);boolean ready=missing>0&&fail!=1&&fail!=8&&!(fail>=2&&fail<=missing+1);ck((p.done!=null)==ready);ck(p.inv.owned.equals(before));if(ready){ck(p.pages.isEmpty()&&p.msgs.isEmpty());if(mode==1)p.done.run();if(mode==2)p.rollback.run();}boolean success=ready&&mode==1;ck(p.pages.equals(success?List.of(ok):missing==0?List.of(already):List.of()));if(success){for(int i=0;i<size;i++)ck(p.inv.owned.get(first+i)==before.getOrDefault(first+i,quantity));ck(p.msgs.size()==missing);if(kind==0)tutorialArmor(p,new L1NpcInstance());else iceCaveSupplies(p,new L1NpcInstance(),kind==1);ck(p.pages.equals(List.of(ok,already)));ck(p.submits==1);}else ck(p.inv.owned.equals(before));}
 static void teleportCase(int map,boolean valid,boolean badRandom,int price,int level,int heading,int cash,int debit){cases++;L1PcInstance p=new L1PcInstance();p.level=level;p.inv.debitResult=debit;if(cash>=0)p.inv.owned.put(40308,cash);Teleport t=new Teleport();t._loc=new L1Location(map,valid);t._price=price;t._heading=heading;L1Location.badRandom=badRandom;boolean random=map==340||map==350||map==360||map==370;boolean admit=valid&&price>=0&&heading>=0&&heading<=7&&(map!=2010||level>=45&&level<=51)&&(price==0||cash>=price);boolean removal=admit&&(!random||!badRandom)&&price>0;boolean success=admit&&(!random||!badRandom)&&(price==0||debit==-1||debit==price);L1NpcHtml out=t.execute("a",p,new L1NpcInstance(),new byte[0]);ck((out==null)==success);ck(p.teleports==(success?1:0));ck(p.inv.removes==(removal?1:0));if(success)ck(p.randomX==(random?11:10));ck(t._loc.x==10);}
 public static void main(String[] a){for(int cls=0;cls<7;cls++)for(int k=0;k<3;k++)for(int mask=0;mask<(k==0?32:2);mask++)for(int fail=0;fail<=8;fail++)for(int mode=0;mode<3;mode++)grantCase(cls,k,mask,fail,mode);for(int map:new int[]{4,2010,340,350,360,370})for(boolean valid:new boolean[]{true,false})for(boolean br:new boolean[]{true,false})for(int price:new int[]{-1,0,10})for(int level:new int[]{44,45,51,52})for(int heading:new int[]{-1,0,7,8})for(int cash:new int[]{-1,0,9,10,11})for(int debit:new int[]{-1,0,5,10})teleportCase(map,valid,br,price,level,heading,cash,debit);System.out.println("PASS cases="+cases+" assertions="+checks);}}
'''
